{"command":"cd /app && python3 - <<'EOF'
import docx
for f in ["skyvault-complaint.docx","holt-eciaa-agreement.docx","meridian-cd-response.docx","pathforge-whitepaper-excerpt.docx"]:
    d = docx.Document(f"data/input_files/{f}")
    print("="*30, f, "="*30)
    for i,p in enumerate(d.paragraphs):
        t = p.text.strip()
        if t:
            print(f"[{i}] {t}")
    for ti,tbl in enumerate(d.tables):
        print(f"--- TABLE {ti} ---")
        for r in tbl.rows:
            print(" | ".join(c.text.strip() for c in r.cells))
EOF"}

{"command":"cd /app && python3 - <<'EOF'
import openpyxl
wb = openpyxl.load_workbook("data/input_files/exhibit-f-forensic-log.xlsx", data_only=True)
print("Sheets:", wb.sheetnames)
for ws in wb.worksheets:
    print("="*20, ws.title, f"dims={ws.dimensions} max_row={ws.max_row} max_col={ws.max_column}", "="*20)
    for row in ws.iter_rows(values_only=True):
        if any(v is not None for v in row):
            print(" | ".join("" if v is None else str(v) for v in row))
EOF"}
